### Correct Program ###

import sys
from typing import List


def can_be_achieved(participants: int, days: int, foods: List[int]) -> bool:
    if days == 0:
        return True

    max_participants = 0
    for food_t_q in foods:
        max_participants += (food_t_q // days)
    return participants <= max_participants


def main():
    data = sys.stdin.read().split('\n')
    first_line = data[0].split()
    participants = int(first_line[0])
    # food_types count not needed beyond reading the line
    foods_line = data[1].split()
    food_types = [int(v) for v in foods_line]

    f_q = {}
    for food_t in food_types:
        if food_t in f_q:
            f_q[food_t] += 1
        else:
            f_q[food_t] = 1

    food_quantity = [num for _, num in f_q.items()]

    inf_days, sup_days = 0, max(food_quantity) if food_quantity else 0

    while inf_days < sup_days:
        s = (inf_days + sup_days + 1) // 2
        if can_be_achieved(participants, s, food_quantity):
            inf_days = s
            if s == 0:
                break
        else:
            sup_days = s - 1

    assert (inf_days == 0 or inf_days == sup_days)
    print(inf_days)


if __name__ == "__main__":
    main()

from collections import Counter

def can_we_give(freq, packets, n):
    fullfilled = 0
    for food_packets in freq.keys():
        fullfilled += freq[food_packets] // packets
    if fullfilled >= n:
        return True
    else:
        return False


def main():
    # Taking input
    n, m = (int(num) for num in input().split())
    A = [int(num) for num in input().split()]
    if m < n:    # Base Case
        print(0)
        return
    freq = Counter(A)    # Frequency of each and every food packets
    # Here l is the minm no.of expedition and r is the
    # maxm no.of expedition (r+1 to ensure r is guaranteed infeasible)
    l, r = 1, max(freq.values()) + 1
    while l + 1 < r:
        mid = (l + r) // 2
        if can_we_give(freq, mid, n):
            l = mid
        else:
            r = mid

    print(l)


if __name__ == '__main__':
    main()

