from collections import Counter

def check(types, qtd_pessoas, dias):
    if dias == 0:
        return False

    for tipo in types:
        qtd_pessoas -= types[tipo] // dias
        if qtd_pessoas <= 0:
            return True

    return False


def busca(types, qtd_pessoas, left, right):
    ans = 0
    while left <= right:
        mid = (left + right) // 2
        if check(types, qtd_pessoas, mid):
            ans = mid
            left = mid + 1
        else:
            right = mid - 1
    return ans


