from collections import Counter

def can_we_give(freq, packets, n):
    fullfilled = 0
    for count in freq.values():
        fullfilled += count // packets
    return fullfilled >= n

def main():
    n, m = map(int, input().split())
    A = list(map(int, input().split()))

    if m < n:
        print(0)
        return

    freq = Counter(A)

    l, r = 1, max(freq.values())
    while l <= r:
        mid = (l + r) // 2
        if can_we_give(freq, mid, n):
            l = mid + 1
        else:
            r = mid - 1

    print(r if r >= 1 else 0)

if __name__ == '__main__':
    main()

def Ludi(t, d):
    s = 0
    if t != 0:
        for i in d:
            s += d[i] // t
        return s
    else:
        return 0

